{"function": "() => {
    const quotes = [];
    // Look for blockquote elements
    document.querySelectorAll('blockquote').forEach(el => quotes.push(el.innerText));
    // Look for elements with quotes (maybe q tags)
    document.querySelectorAll('q').forEach(el => quotes.push(el.innerText));
    // Look for any paragraph that contains a quotation mark and a dash
    const paragraphs = document.querySelectorAll('p');
    paragraphs.forEach(p => {
        const text = p.innerText;
        if (text.includes('\"') && text.includes('—')) {
            quotes.push(text);
        }
    });
    return quotes;
}"}

